<!-- Synthetic normal-UI contract calibration. Not a Cortexium implementation. -->
<script setup lang="ts">
import {ref,onMounted} from 'vue'
const s=ref<any>({}),email=ref(''),password=ref(''),input=ref(''),flow=ref(''),instruction=ref(''),fn=ref('report-v1'),worker=ref('fixture-review'),denied=ref(false),conflict=ref(false)
async function load(){const id=new URL(location.href).searchParams.get('run');const r=await fetch('/state'+(id?'?run='+id:''));if(r.status===403){denied.value=true;return}if(r.status===401){s.value={};return}s.value=await r.json();fn.value=s.value.Function;worker.value=s.value.Worker;denied.value=false}
async function action(Action:string,extra:any={}){const r=await fetch('/action',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({Action,...extra})});if(r.status===409){conflict.value=true;return}if(r.status===403){denied.value=true;return}if(!r.ok)throw Error('fixture request failed');s.value=await r.json();fn.value=s.value.Function;worker.value=s.value.Worker;denied.value=false;if(Action==='new-flow'){history.pushState({},'','/');flow.value=''}if(Action==='run-flow'||Action==='open-run'){history.pushState({},'','/?run='+s.value.Current.ID)}}
onMounted(load)
</script>
<template>
<main>
<header><h1>Runner local proof fixture</h1><p>Reusable review → named report formatter → exact human acceptance</p></header>
<section v-if="!s.User&&!denied"><h2>Sign in to the isolated workspace</h2><label>Email <input data-runner="email" v-model="email"></label><label>Password <input data-runner="password" type="password" v-model="password"></label><button data-runner="sign-in" @click="action('login',{Email:email,Password:password})">Sign in</button></section>
<section v-if="denied" data-runner="access-denied"><h2>Access denied</h2><p>Your current workspace membership does not permit reading this work.</p></section>
<template v-if="s.User&&!denied">
<section><label>Workspace <select data-runner="workspace" :value="s.Workspace" @change="action('workspace',{Workspace:($event.target as HTMLSelectElement).value})"><option value="personal-alice">Alice personal</option><option value="personal-bob">Bob personal</option><option value="shared-alpha">Shared Alpha</option></select></label><button data-runner="new-flow" @click="action('new-flow')">New flow</button><button data-runner="work-overview">Work overview</button></section>
<section><h2>Configure a reusable flow</h2><label>Flow name <input data-runner="flow-name" v-model="flow"></label><label>Agent version <select data-runner="agent-version"><option value="review-v1">Review v1</option></select></label><label>Skill version <select data-runner="skill-version"><option value="supplied-text-v1">Supplied text v1</option></select></label><label>Named function <select data-runner="function-version" v-model="fn"><option value="report-v1">Report v1</option><option value="fixture-failure-v1">Failing fixture formatter v1</option></select></label><label>Worker <select data-runner="worker" v-model="worker"><option value="fixture-review">Permitted supplied-text Worker</option><option value="fixture-unsupported">Unsupported fixture Worker</option></select></label><ol data-runner="typed-steps"><li>Agent: text → review</li><li>Report function: review → report</li><li>Human: report → saved exact version</li></ol><button data-runner="save-flow" @click="action('save-flow',{Function:fn,Worker:worker})">Save flow</button><p data-runner="frozen-versions">review-v1 · supplied-text-v1 · {{fn}}</p></section>
<section><h2>Run the saved flow</h2><label>Supplied text <textarea data-runner="supplied-text" v-model="input"></textarea></label><button data-runner="run-flow" @click="action('run-flow',{Input:input})">Run flow</button></section>
<section v-if="s.Current"><h2>Run <span data-runner="run-id">{{s.Current.ID}}</span></h2><p data-runner="run-state">{{s.Current.State}}</p><p>Current step: <span data-runner="current-step">Human</span>; responsible: <span data-runner="responsible-party">{{s.User}}</span></p><p data-runner="run-versions">review-v1 · supplied-text-v1 · report-v1</p><h3>Retained input</h3><p data-runner="retained-input">{{s.Current.Input}}</p><h3>Report version <span data-runner="result-version">{{s.Current.Version}}</span></h3><p data-runner="current-result">{{s.Current.Result}}</p><p>Model invocations: <span data-runner="model-invocations">{{s.Current.Invocations}}</span></p><p data-runner="failure-reason">{{s.Current.Failure}}</p><p v-if="conflict" data-runner="version-conflict">Version conflict: refresh the exact current version.</p><label>Revision instruction <input data-runner="revision-instruction" v-model="instruction"></label><button data-runner="request-revision" @click="action('request-revision')">Request revision</button><button data-runner="accept-result" :disabled="s.Current.State!=='Awaiting acceptance'" @click="action('accept-result',{Version:s.Current.Version})">Accept exact result</button><button data-runner="recover-receipt" @click="action('recover-receipt')">Recover retained receipt</button><button data-runner="cancel-run" @click="action('cancel-run')">Cancel run</button><button data-runner="retry-run" disabled>Replacement unavailable while uncertain</button><button data-runner="run-again" @click="input=''">Run again</button><aside v-if="s.Current.State==='Accepted'"><h3>Saved result</h3><p data-runner="saved-result">{{s.Current.Result}}</p><p>Accepted version <span data-runner="accepted-version">{{s.Current.Accepted}}</span></p></aside></section>
<section><h2>Retained work</h2><button v-for="r in s.Runs" :key="r.ID" data-runner="open-run" @click="action('open-run',{Run:r.ID})">{{r.ID}} · {{r.State}}</button></section>
<section><h2>Workspace controls</h2><button data-runner="workspace-members">Workspace members</button><button data-runner="remove-bob" @click="action('remove-bob')">Remove Bob membership</button><p data-runner="membership-state">{{s.Member?'Member':'Removed'}}</p><button data-runner="worker-settings">Worker settings</button><button data-runner="revoke-worker-grant" @click="action('revoke-worker-grant')">Revoke Worker grant</button><button data-runner="grant-worker" @click="action('grant-worker')">Grant Worker</button><p data-runner="worker-grant-state">{{s.Grant?'Granted':'Revoked'}}</p></section>
</template>
</main>
</template>
<style scoped>
main{max-width:1000px;margin:0 auto;padding:20px;font-family:system-ui;color:#173040}header,section{border:1px solid #cbd6dc;border-radius:10px;padding:16px;margin-bottom:16px;background:#fff}h1,h2,h3{margin:0 0 12px}label{display:block;margin:10px 0}input,select,textarea{display:block;width:100%;box-sizing:border-box;padding:10px;border:1px solid #8097a6;border-radius:5px;font:inherit}button{padding:10px 14px;margin:4px;border:1px solid #426578;border-radius:6px;font:inherit;color:#173040;background:#e7f4fa}p{overflow-wrap:anywhere}aside{background:#eff9f0;padding:12px}button:disabled{opacity:.5}
</style>
